import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.DajbkT6K.js";const n="/aibutler/docs/img/en/plugin-tetris.png",g=JSON.parse('{"title":"Plugins","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/plugins.md","filePath":"en/guide/plugins.md"}'),s={name:"en/guide/plugins.md"};function l(r,e,u,p,d,c){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h1><p class="big-note">You don&#39;t need to know how to code. Just tell your persona what tool you want.</p><p>A plugin is a small tool with its own interface: an expense tracker, a to-do board, flashcards, a timer, a mini game, and so on. Your persona writes it, installs it, and opens it for you on the spot.</p><h2 id="have-your-persona-build-one-for-you" tabindex="-1">Have your persona build one for you <a class="header-anchor" href="#have-your-persona-build-one-for-you" aria-label="Permalink to &quot;Have your persona build one for you&quot;">​</a></h2><p>Describe what you want in plain language — the more specific, the better:</p><blockquote><p>Build me a Tetris game.</p></blockquote><blockquote><p>Build me a small expense tracker: it should log how much I spent and on what, and show monthly totals.</p></blockquote><blockquote><p>My kid needs to practice tracing Chinese characters — build a tracing exercise.</p></blockquote><p>It will write the plugin, install it, and open it so you can see it.</p><p><img src="'+n+'" alt="A Tetris game built by the persona"></p><p>If you&#39;re not happy with it, just keep talking:</p><blockquote><p>Make the blocks fall a bit slower.</p></blockquote><blockquote><p>Add a pie chart broken down by category.</p></blockquote><p>A plugin you&#39;ve had built stays around — next time, just say &quot;open the expense tracker&quot; and it comes right back.</p><h2 id="using-existing-plugins" tabindex="-1">Using existing plugins <a class="header-anchor" href="#using-existing-plugins" aria-label="Permalink to &quot;Using existing plugins&quot;">​</a></h2><p>Ask it what it has:</p><blockquote><p>What plugins do you have?</p></blockquote><blockquote><p>Is there one for a pomodoro timer?</p></blockquote><p>It will find it and open it for you. For ones you use often, you can have it pin them to the side of the window:</p><blockquote><p>Pin the to-do board.</p></blockquote><p>Always-open tools such as a music player sit in the right side panel (under the top board in the stacked layout) instead of above the chat, and switching personas doesn&#39;t stop the music.</p><h2 id="are-plugins-safe" tabindex="-1">Are plugins safe <a class="header-anchor" href="#are-plugins-safe" aria-label="Permalink to &quot;Are plugins safe&quot;">​</a></h2><ul><li>Plugins run in an isolated sandbox and can&#39;t touch your files or system.</li><li>They can only do a few things: show an interface, store their own data, hand results back to the persona, fetch data from sites you&#39;ve approved, and so on.</li><li>Plugins that need a key store it in your local vault — the plugin itself never sees the raw value.</li><li>Plugins from outside sources must pass a signature check before they can be installed. Plugins your persona writes for you live on your own computer and don&#39;t need one.</li></ul><h2 id="for-developers" tabindex="-1">For developers <a class="header-anchor" href="#for-developers" aria-label="Permalink to &quot;For developers&quot;">​</a></h2><p>A plugin is just a JSON file — drop it into the <code>packages.local/</code> folder in your data directory and it installs automatically, no restart needed. See <a href="/aibutler/docs/en/guide/developers.html">Developers</a> for the format, available capabilities, and examples.</p>',25)])])}const b=o(s,[["render",l]]);export{g as __pageData,b as default};
